+pub const ALPHA_5: f64 = 2.0 * PI; // 2π (Unity Constraint: ALPHA_4 * ALPHA_5 = 1)
+
+/// Represents a high-dimensional vector in continuous R⁴ Space.
+#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
+pub struct R4Vector {
+    pub x: f64,
+    pub y: f64,
+    pub z: f64,
+    pub w: f64,
+}
+
+impl R4Vector {
+    pub fn origin() -> Self {
+        Self {
+            x: 0.0,
+            y: 0.0,
+            z: 0.0,
+            w: 0.0,
+        }
+    }
+
+    pub fn minkowski_norm(&self) -> f64 {
+        -(self.w * self.w) + (self.x * self.x) + (self.y * self.y) + (self.z * self.z)
+    }
+
+    pub fn tangent_direction_from_origin(&self) -> Self {
+        let magnitude =
+            (self.x * self.x + self.y * self.y + self.z * self.z + self.w * self.w).sqrt();
+        if magnitude == 0.0 {
+            Self::origin()
+        } else {
+            Self {
+                x: self.x / magnitude,
+                y: self.y / magnitude,
+                z: self.z / magnitude,
+                w: self.w / magnitude,
+            }
+        }
+    }
+}
