+    total_cap: usize,
+    min_first: usize,
+    min_second: usize,
+    min_third: usize,
+) -> (usize, usize, usize) {
+    let total_cap = total_cap.max(1);
+    let min_first = min_first.max(1);
+    let min_second = min_second.max(1);
+    let min_third = min_third.max(1);
+
+    let mut best = (1, total_cap, 1);
