+    fn get_sentence_prime_product(&self, words: &[String]) -> u128 {
+        let mut prod: u128 = 1;
+        let stopwords = query_stopwords();
+        for w in words {
+            if stopwords.contains(&w.as_str()) {
+                continue;
+            }
+            if let Some(&p) = self.word_primes.get(w) {
+                prod = prod.saturating_mul(p as u128);
+            }
+        }
+        prod
