+        if start_key.is_none() {
+            // Find any trigram starting with prompt's last word
+            if let Some(last_word) = words.last() {
+                for key in self.transitions_2nd.keys() {
+                    if key.starts_with(last_word) {
+                        start_key = Some(key.clone());
+                        break;
