+/// Derived at construction from its definition; never hand-entered.
+/// POPCOUNT[x] = number of set bits of x — the stratum observable.
+pub fn derive_popcount_table() -> [u8; 256] {
+    let mut t = [0u8; 256];
+    for x in 0..=255u8 {
+        t[x as usize] = x.count_ones() as u8;
+    }
